import { expect, test } from "vitest";
import { dropLast } from "./dropLast";
import { pipe } from "./pipe";
import { takeLast } from "./takeLast";

const counts = [
  2.9,
  0,
  -1,
  Number.NEGATIVE_INFINITY,
  Number.NaN,
  Number.POSITIVE_INFINITY,
];

test.each(counts)("takeLast applies the shared count policy for %s", (count) => {
  const data = [1, 2, 3, 4, 5];
  const expected = count === 2.9 ? [4, 5] : count > 0 ? data : [];

  expect(takeLast(data, count)).toStrictEqual(expected);
  expect(takeLast(count)(data)).toStrictEqual(expected);
  expect(pipe(data, takeLast(count))).toStrictEqual(expected);
  expect(data).toStrictEqual([1, 2, 3, 4, 5]);
});

test.each(counts)("dropLast applies the shared count policy for %s", (count) => {
  const data = [1, 2, 3, 4, 5];
  const expected = count === 2.9 ? [1, 2, 3] : count > 0 ? [] : data;

  expect(dropLast(data, count)).toStrictEqual(expected);
  expect(dropLast(count)(data)).toStrictEqual(expected);
  expect(pipe(data, dropLast(count))).toStrictEqual(expected);
  expect(data).toStrictEqual([1, 2, 3, 4, 5]);
});

test("supports readonly arrays and returns new arrays", () => {
  const data: readonly number[] = [1, 2, 3];

  const taken = takeLast(data, Number.POSITIVE_INFINITY);
  const dropped = dropLast(Number.NEGATIVE_INFINITY)(data);

  expect(taken).not.toBe(data);
  expect(dropped).not.toBe(data);
