+import { expect, test } from "vitest";
+import { clamp, pipe } from "./index";
+
+test.each([
+  [-5, 0],
+  [5, 5],
+  [15, 10],
+] as const)("normalizes reversed finite bounds in data-first use", (value, expected) => {
+  expect(clamp(value, { min: 10, max: 0 })).toBe(expected);
+});
+
+test("normalizes reversed finite bounds in data-last and pipe use", () => {
+  const limits = { min: 10, max: 0 } as const;
+
+  expect(clamp(limits)(-5)).toBe(0);
+  expect(pipe(15, clamp(limits))).toBe(10);
+});
+
+test("does not mutate frozen limits", () => {
+  const limits = Object.freeze({ min: 10, max: 0 });
+
+  expect(clamp(5, limits)).toBe(5);
+  expect(limits).toStrictEqual({ min: 10, max: 0 });
+});
+
+test("observes updated limits on every curried invocation", () => {
+  const limits = { min: 10, max: 0 };
+  const curriedClamp = clamp(limits);
+
+  expect(curriedClamp(15)).toBe(10);
+  limits.min = 20;
+  limits.max = 5;
+  expect(curriedClamp(15)).toBe(15);
+});
+
+test("preserves behavior for non-finite and missing bounds", () => {
+  expect(clamp(5, {})).toBe(5);
+  expect(clamp(5, { min: Number.NaN, max: 10 })).toBe(5);
+  expect(clamp(15, { min: 0, max: Number.NaN })).toBe(15);
+  expect(clamp(5, { min: Number.POSITIVE_INFINITY })).toBe(
+    Number.POSITIVE_INFINITY,
+  );
+  expect(clamp(5, { max: Number.NEGATIVE_INFINITY })).toBe(
+    Number.NEGATIVE_INFINITY,
+  );
